public static class CloudPilotCanopyPass {
 const string K="Assets/ParkingLotEnvironment/CloudPilot", T="Assets/_Parkside/Scenes/ParklingLot.unity";
 static string output; static GameObject pilot; static StringBuilder report=new StringBuilder();
 static Camera Eye=>pilot.GetComponentInChildren<Camera>();
 static void Check(){if(File.Exists("/workspaces/parkside-setup/STOP"))throw new Exception("STOP");}
 static void Open(){Check();output=File.ReadAllText(K+"/Inspection~/full-canopy-current.txt").Trim();EditorSceneManager.OpenScene(T);pilot=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name=="ParkingLot_CornerPilot_Root");if(QualitySettings.shadows!=ShadowQuality.Disable||QualitySettings.antiAliasing!=0)throw new Exception("Unexpected native quality");}
 static void Note(string s){report.AppendLine(s);File.WriteAllText(output+"/report.txt",report.ToString());Debug.Log("CANOPY "+s);}
 static void Persist(UnityEngine.Object o){EditorUtility.SetDirty(o);if(PrefabUtility.IsPartOfPrefabInstance(o))PrefabUtility.RecordPrefabInstancePropertyModifications(o);}
 static MeshFilter[] Leaves()=>pilot.GetComponentsInChildren<MeshFilter>().Where(f=>f.name.ToLower().Contains("leaves")&&!f.name.StartsWith("Daylight_")).ToArray();
 static Material Material(){var path=K+"/Canopy/LeafDoubleSided.mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(m==null){m=new Material(Shader.Find("Parkside/CloudPilot/LeafDoubleSided"));m.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(K+"/BakedLighting/LeafRGBA_0.png");m.color=new Color(.72f,.80f,.64f,1);m.SetFloat("_Cutoff",.28f);m.doubleSidedGI=true;AssetDatabase.CreateAsset(m,path);}return m;}
 static Mesh Cards(Mesh src){string path=K+"/Canopy/LeafCardsAligned.asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(mesh!=null)return mesh;
 var original=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/ParkingLotEnvironment/Meshes/RealismDetails/Tree_leaf_island_cards.asset");if(original==null)throw new Exception("No full leaf cards");mesh=UnityEngine.Object.Instantiate(original);var b=mesh.bounds;var target=src.bounds;Note("Align cards source="+b+" target="+target);var ratio=new Vector3(target.size.x/b.size.x,target.size.y/b.size.y,target.size.z/b.size.z);var v=mesh.vertices;for(int i=0;i<v.Length;i++)v[i]=Vector3.Scale(v[i]-b.center,ratio)+target.center;mesh.vertices=v;mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,path);return mesh;}
 public static void Compare(){try{Open();Note("Native GPU="+SystemInfo.graphicsDeviceName+" shadows="+QualitySettings.shadows+" AA="+QualitySettings.antiAliasing);foreach(var f in Leaves())Note("Leaf="+PathOf(f.transform)+" mesh="+AssetDatabase.GetAssetPath(f.sharedMesh)+" v="+f.sharedMesh.vertexCount+" tri="+f.sharedMesh.triangles.Length/3+" localBounds="+f.sharedMesh.bounds+" world="+f.GetComponent<Renderer>().bounds);
 Capture("compare-first-frame",Eye.transform.position,Eye.transform.rotation,960,540);Capture("compare-warmup",Eye.transform.position,Eye.transform.rotation,960,540);Capture("compare-before-whole",Eye.transform.position,Eye.transform.rotation);
 var leaf=Leaves().OrderBy(f=>Vector3.Distance(f.transform.position,new Vector3(10,0,-1))).First();Note("Representative="+PathOf(leaf.transform));var fills=leaf.transform.parent.GetComponentsInChildren<Transform>().Where(t=>t.name.StartsWith("Daylight_CanopyFill")).ToArray();foreach(var f in fills)f.gameObject.SetActive(false);
 leaf.GetComponent<Renderer>().sharedMaterial=Material();Capture("compare-skinny-double-whole",Eye.transform.position,Eye.transform.rotation);
 leaf.sharedMesh=Cards(leaf.sharedMesh);Capture("compare-fullcards-whole",Eye.transform.position,Eye.transform.rotation);
 var center=leaf.GetComponent<Renderer>().bounds.center;var pos=center+new Vector3(-5,-.5f,-8);Capture("compare-fullcards-tree",pos,Quaternion.LookRotation(center-pos));
 Note("COMPARE_ONLY scene unsaved; material and mesh clones saved");AssetDatabase.SaveAssets();EditorApplication.Exit(0);
 }catch(Exception e){Fail(e);}}
 static double bakeStart; static int frame; static bool baking;
 public static void ApplyAndBake(){try{Open();var leaves=Leaves();var cards=Cards(leaves.First().sharedMesh);var mat=Material();int before=0;foreach(var f in leaves){before+=f.sharedMesh.triangles.Length/3;f.sharedMesh=cards;f.GetComponent<Renderer>().sharedMaterial=mat;Persist(f);Persist(f.GetComponent<Renderer>());}
 var fills=pilot.GetComponentsInChildren<Transform>().Where(t=>t.name.StartsWith("Daylight_CanopyFill_")).ToArray();foreach(var f in fills)UnityEngine.Object.DestroyImmediate(f.gameObject);
 Note("Applied full cards trees="+leaves.Length+" cardsTriPerTree="+cards.triangles.Length/3+" oldBaseTotal="+before+" removedDuplicateCanopies="+fills.Length+" normalBackface=VFACE tangentZ flip; mask=matching RGBA; emission=none");
 var aa=Eye.GetComponent<MapCameraFXAA>();if(aa==null)aa=Eye.gameObject.AddComponent<MapCameraFXAA>();aa.edgeShader=Shader.Find("Hidden/Parkside/CloudPilot/MapCameraFXAA");Persist(aa);
 var settings=UnityEngine.Object.Instantiate(Lightmapping.lightingSettings);settings.name="FullCanopyCPU";settings.autoGenerate=false;settings.lightmapper=LightingSettings.Lightmapper.ProgressiveCPU;settings.lightmapResolution=20;settings.lightmapMaxSize=2048;settings.directSampleCount=64;settings.indirectSampleCount=64;settings.environmentSampleCount=48;settings.ao=true;settings.aoMaxDistance=1.2f;settings.aoExponentDirect=.4f;settings.aoExponentIndirect=.8f;AssetDatabase.CreateAsset(settings,K+"/Canopy/FullCanopyCPU.lighting");Lightmapping.lightingSettings=settings;
 int ground=0,excluded=0,walls=0,casters=0;foreach(var r in pilot.GetComponentsInChildren<MeshRenderer>()){
 string path=PathOf(r.transform);var flags=GameObjectUtility.GetStaticEditorFlags(r.gameObject);bool organic=System.Text.RegularExpressions.Regex.Replace(path,"street","",System.Text.RegularExpressions.RegexOptions.IgnoreCase).IndexOf("tree",StringComparison.OrdinalIgnoreCase)>=0||path.Contains("Shrub")||path.IndexOf("vehicle",StringComparison.OrdinalIgnoreCase)>=0||path.Contains("Truck");bool paint=path.Contains("ParkingPaint");bool tiny=paint||path.Contains("Cable")||path.Contains("Window")||path.Contains("Glass")||path.Contains("Frame")||path.Contains("Blind")||r.bounds.size.sqrMagnitude<.12f||r.GetComponent<TextMesh>()!=null;
 if(tiny||path.Contains("Daylight_FinalGround")){GameObjectUtility.SetStaticEditorFlags(r.gameObject,flags&~StaticEditorFlags.ContributeGI);r.scaleInLightmap=0;r.receiveGI=ReceiveGI.LightProbes;if(paint){r.shadowCastingMode=ShadowCastingMode.Off;var tr=r.transform;Note("Paint bounds="+r.bounds+" localScale="+tr.localScale);var mats=r.sharedMaterials;for(int j=0;j<mats.Length;j++){var m=new Material(mats[j]);m.name="PaintNoDarkEdges_"+j;m.SetFloat("_Glossiness",.05f);AssetDatabase.CreateAsset(m,K+"/Canopy/"+m.name+".mat");mats[j]=m;}r.sharedMaterials=mats;}excluded++;}
 else {GameObjectUtility.SetStaticEditorFlags(r.gameObject,flags|StaticEditorFlags.ContributeGI);r.receiveGI=ReceiveGI.Lightmaps;r.shadowCastingMode=ShadowCastingMode.TwoSided;if(organic){r.scaleInLightmap=0;casters++;}else if(path.Contains("Zone_Asphalt")||path.Contains("Sidewalk")){r.scaleInLightmap=1.8f;ground++;}else{r.scaleInLightmap=.18f;walls++;}}
 Persist(r);Persist(r.gameObject);}
 foreach(var l in pilot.GetComponentsInChildren<Light>()){l.transform.rotation=Quaternion.Euler(52,145,0);l.lightmapBakeType=LightmapBakeType.Mixed;Persist(l.transform);Persist(l);}
 AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());File.WriteAllText(output+"/checkpoint-applied.txt","Scene saved before bake; full leaf card checkpoint. "+DateTime.UtcNow.ToString("o"));
 string work=K+"/Canopy/FullCanopyBakeWork.unity";EditorSceneManager.SaveScene(SceneManager.GetActiveScene(),work);Note("BAKE_SETUP pavement="+ground+" walls="+walls+" microExcluded="+excluded+" casters="+casters+" 20tex/m max2048 samples64/64/48 nativeShadowsDisable AA0");
 bakeStart=EditorApplication.timeSinceStartup;baking=true;EditorApplication.update+=BakeTick;if(!Lightmapping.BakeAsync())throw new Exception("Bake rejected");
 }catch(Exception e){Fail(e);}}
 public static void BalancedBake(){try{Open();var cards=AssetDatabase.LoadAssetAtPath<Mesh>(K+"/Canopy/LeafCardsAligned.asset");var mat=Material();int shrubs=0;foreach(var f in pilot.GetComponentsInChildren<MeshFilter>().Where(f=>f.name.StartsWith("Street_RealMeshShrub_"))){f.sharedMesh=cards;f.GetComponent<Renderer>().sharedMaterial=mat;Persist(f);Persist(f.GetComponent<Renderer>());shrubs++;}
 var paint=pilot.transform.Find("Zone_ParkingPaint");var position=paint.localPosition;position.y+=.008f;paint.localPosition=position;Persist(paint);Note("Raise parking paint 8mm to separate coplanar pavement. Full cards also replace same-source shrub meshes="+shrubs);
 var settings=UnityEngine.Object.Instantiate(Lightmapping.lightingSettings);settings.name="FullCanopyBalancedCPU";settings.lightmapResolution=12;settings.lightmapMaxSize=1024;settings.directSampleCount=24;settings.indirectSampleCount=32;settings.environmentSampleCount=24;AssetDatabase.CreateAsset(settings,K+"/Canopy/FullCanopyBalancedCPU.lighting");Lightmapping.lightingSettings=settings;
 foreach(var r in pilot.GetComponentsInChildren<MeshRenderer>()){var path=PathOf(r.transform);if(r.scaleInLightmap>0){r.scaleInLightmap=path.Contains("Zone_Asphalt")||path.Contains("Sidewalk")?1.25f:.12f;Persist(r);}}
 AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene(),K+"/Canopy/BalancedBakeWork.unity");Note("BALANCED_BAKE native quality unchanged; requested12tex/m groundScale1.25 max1024 samples24/32/24. Previous process exit -9 at235.4sec; not a successful bake.");bakeStart=EditorApplication.timeSinceStartup;EditorApplication.update+=BakeTick;if(!Lightmapping.BakeAsync())throw new Exception("Balanced bake rejected");}catch(Exception e){Fail(e);}}
 public static void StaticShadeBake(){try{Open();var filter=pilot.transform.Find("Zone_ParkingPaint").GetComponentInChildren<MeshFilter>();var source=filter.sharedMesh;var mesh=UnityEngine.Object.Instantiate(source);var v=mesh.vertices;var ind=mesh.triangles;var keep=new System.Collections.Generic.List<int>();for(int i=0;i<ind.Length;i+=3){var normal=Vector3.Cross(v[ind[i+1]]-v[ind[i]],v[ind[i+2]]-v[ind[i]]);if(normal.y>0){keep.Add(ind[i]);keep.Add(ind[i+1]);keep.Add(ind[i+2]);}}if(keep.Count==0)throw new Exception("No upward paint triangles");for(int i=0;i<v.Length;i++)v[i].y=-.004f;mesh.vertices=v;mesh.triangles=keep.ToArray();mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,K+"/Canopy/ParkingPaintFlat.asset");filter.sharedMesh=mesh;Persist(filter);var paint=pilot.transform.Find("Zone_ParkingPaint");var pos=paint.localPosition;pos.y=0;paint.localPosition=pos;Persist(paint);Note("Paint top-only triangles="+keep.Count/3+" old="+ind.Length/3+" y=-.004 vs ground-.006; no side faces or cast shadows");
 var settings=UnityEngine.Object.Instantiate(Lightmapping.lightingSettings);settings.name="FullCanopyStaticShadeCPU";AssetDatabase.CreateAsset(settings,K+"/Canopy/FullCanopyStaticShadeCPU.lighting");Lightmapping.lightingSettings=settings;
 foreach(var l in pilot.GetComponentsInChildren<Light>()){l.lightmapBakeType=LightmapBakeType.Baked;l.transform.rotation=Quaternion.Euler(48,-35,0);Persist(l);Persist(l.transform);}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene(),K+"/Canopy/StaticShadeBakeWork.unity");Note("STATIC_SHADE_TEST Baked sun48,-35 for persisted static lightmaps and light probes; native shadows Disable AA0 unchanged");bakeStart=EditorApplication.timeSinceStartup;EditorApplication.update+=BakeTick;if(!Lightmapping.BakeAsync())throw new Exception("Static shade bake rejected");}catch(Exception e){Fail(e);}}
 public static void FixPaintNormals(){try{Open();var old=pilot.transform.Find("Zone_ParkingPaint").GetComponentInChildren<MeshRenderer>();var filter=old.GetComponent<MeshFilter>();Note("Imported paint transform lossyScale="+filter.transform.lossyScale+" rotation="+filter.transform.rotation.eulerAngles+" worldBounds="+old.bounds);var src=filter.sharedMesh;var v=src.vertices;for(int i=0;i<v.Length;i++){v[i]=filter.transform.TransformPoint(v[i]);v[i].y=-.004f;v[i]=pilot.transform.InverseTransformPoint(v[i]);}var ind=src.triangles;for(int i=0;i<ind.Length;i+=3)if(Vector3.Cross(v[ind[i+1]]-v[ind[i]],v[ind[i+2]]-v[ind[i]]).y<0){int t=ind[i+1];ind[i+1]=ind[i+2];ind[i+2]=t;}
 var mesh=new Mesh();mesh.name="ParkingPaint_WorldUp";mesh.vertices=v;mesh.triangles=ind;mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,K+"/Canopy/ParkingPaintWorldUp.asset");var go=new GameObject("CanopyPass_ParkingPaint_WorldUp");go.transform.SetParent(pilot.transform,false);go.AddComponent<MeshFilter>().sharedMesh=mesh;var r=go.AddComponent<MeshRenderer>();var mat=new Material(Shader.Find("Standard"));mat.name="ParkingPaint_ProbeLit";mat.color=new Color(.70f,.69f,.64f);mat.SetFloat("_Glossiness",.05f);AssetDatabase.CreateAsset(mat,K+"/Canopy/ParkingPaintProbeLit.mat");r.sharedMaterial=mat;r.shadowCastingMode=ShadowCastingMode.Off;r.receiveGI=ReceiveGI.LightProbes;r.lightProbeUsage=LightProbeUsage.BlendProbes;var anchor=new GameObject("Paint_ProbeSample");anchor.transform.SetParent(go.transform,false);anchor.transform.localPosition=new Vector3(0,.6f,0);r.probeAnchor=anchor.transform;old.enabled=false;Persist(old);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());Note("World-up paint saved triangles="+ind.Length/3+" bounds="+r.bounds+" probes=BlendProbes anchorY=.6 not emissive. Original pilot mesh renderer disabled only; preserved root untouched.");EditorApplication.Exit(0);}catch(Exception e){Fail(e);}}
 public static void FixOuterProbe(){try{Open();var r=pilot.GetComponentsInChildren<MeshRenderer>().Single(x=>x.name=="Daylight_FinalGround");var anchor=new GameObject("OuterGround_ProbeSample");anchor.transform.SetParent(pilot.transform,false);anchor.transform.localPosition=new Vector3(0,.6f,0);r.lightProbeUsage=LightProbeUsage.BlendProbes;r.probeAnchor=anchor.transform;Persist(r);EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());Note("Outer non-baked ground now samples persisted light probes at0,.6,0. No emissive or quality override.");EditorApplication.Exit(0);}catch(Exception e){Fail(e);}}
 public static void FastCapture(){try{Open();frame=-2;EditorApplication.update+=FastTick;}catch(Exception e){Fail(e);}}
 static void FastTick(){try{var pos=Eye.transform.position;var rot=Eye.transform.rotation;var aa=Eye.GetComponent<MapCameraFXAA>();if(frame<0)Capture("final-warmup-"+(frame+2),pos,rot,960,540);else if(frame==0){aa.enabled=false;Capture("after-eye-no-aa",pos,rot);aa.enabled=true;}else if(frame==1)Capture("after-eye-native",pos,rot);else if(frame==2)Capture("after-side3m-native",pos+Vector3.right*3,rot,960,540);else if(frame==3)Capture("after-aerial-native",new Vector3(23,26,-28),Quaternion.LookRotation(new Vector3(-23,-25,30)),960,540);else{EditorApplication.update-=FastTick;File.WriteAllText(output+"/final-outer-capture-report.txt",report.ToString());EditorApplication.Exit(0);}frame++;}catch(Exception e){Fail(e);}}
 public static void CaptureMovement(){try{Open();report.Clear();frame=-2;EditorApplication.update+=MovementTick;}catch(Exception e){Fail(e);}}
 static void MovementTick(){try{Check();var pos=Eye.transform.position;var rot=Eye.transform.rotation;if(frame<0)Capture("move-warmup-"+(frame+2),pos,rot,960,540);else if(frame<8)Capture("movement-"+frame.ToString("D2"),pos+Vector3.forward*(frame*.45f),rot,960,540);else {EditorApplication.update-=MovementTick;File.WriteAllText(output+"/movement-capture-report.txt",report.ToString());EditorApplication.Exit(0);}frame++;}catch(Exception e){Fail(e);}}
 static bool beforeCapture;
 public static void CaptureBefore(){try{Open();beforeCapture=true;report.Clear();EditorSceneManager.OpenScene(K+"/Canopy/BeforeComparison.unity");pilot=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name=="ParkingLot_CornerPilot_Root");Note("BASELINE backup scene copy, same saved camera, nativeShadows="+QualitySettings.shadows+" nativeAA="+QualitySettings.antiAliasing);frame=-3;EditorApplication.update+=BeforeTick;}catch(Exception e){Fail(e);}}
 static void BeforeTick(){try{Check();var pos=Eye.transform.position;var rot=Eye.transform.rotation;if(frame<0)Capture("before-warmup-"+(frame+3),pos,rot,960,540);else if(frame==0)Capture("before-eye-native",pos,rot);else if(frame==1)Capture("before-aerial-native",new Vector3(23,26,-28),Quaternion.LookRotation(new Vector3(-23,-25,30)));else {EditorApplication.update-=BeforeTick;File.WriteAllText(output+"/before-capture-report.txt",report.ToString());EditorApplication.Exit(0);}frame++;}catch(Exception e){Fail(e);}}
 static void BakeTick(){try{Check();if(EditorApplication.timeSinceStartup-bakeStart>360)throw new Exception("Bake timeout");if(EditorApplication.timeSinceStartup-bakeStart<5||Lightmapping.isRunning)return;EditorApplication.update-=BakeTick;baking=false;Note("Baked seconds="+(EditorApplication.timeSinceStartup-bakeStart)+" maps="+LightmapSettings.lightmaps.Length+" data="+AssetDatabase.GetAssetPath(Lightmapping.lightingDataAsset));if(LightmapSettings.lightmaps.Length==0)throw new Exception("No lightmap");
 foreach(var probe in pilot.GetComponentsInChildren<ReflectionProbe>()){probe.enabled=true;string path=K+"/Canopy/FullCanopyReflection.exr";if(!Lightmapping.BakeReflectionProbe(probe,path))throw new Exception("Reflection bake rejected");AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);probe.mode=ReflectionProbeMode.Custom;probe.customBakedTexture=AssetDatabase.LoadAssetAtPath<Texture>(path);Persist(probe);}
 EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene(),T);AssetDatabase.SaveAssets();File.WriteAllText(output+"/bake-saved.txt",DateTime.UtcNow.ToString("o"));EditorApplication.Exit(0);
 }catch(Exception e){Fail(e);}}
 public static void CaptureSaved(){try{Open();report.Clear();Note("COLD_OPEN nativeShadows="+QualitySettings.shadows+" nativeAA="+QualitySettings.antiAliasing+" GPU="+SystemInfo.graphicsDeviceName+" savedCamera="+Eye.name+" components="+string.Join(",",Eye.GetComponents<Component>().Select(c=>c.GetType().Name)));Note("Maps="+LightmapSettings.lightmaps.Length+" data="+AssetDatabase.GetAssetPath(Lightmapping.lightingDataAsset)+" fullCanopies="+Leaves().Length+" duplicateFillCount="+pilot.GetComponentsInChildren<Transform>().Count(t=>t.name.StartsWith("Daylight_CanopyFill")));foreach(var lm in LightmapSettings.lightmaps)Note("Lightmap="+lm.lightmapColor.width+"x"+lm.lightmapColor.height);foreach(var p in pilot.GetComponentsInChildren<ReflectionProbe>())Note("Reflection="+p.mode+" "+AssetDatabase.GetAssetPath(p.customBakedTexture));foreach(var shader in new[]{Shader.Find("Parkside/CloudPilot/LeafDoubleSided"),Shader.Find("Hidden/Parkside/CloudPilot/MapCameraFXAA")})foreach(var msg in ShaderUtil.GetShaderMessages(shader))Note("ShaderMessage="+msg.severity+" "+msg.message);frame=-3;EditorApplication.update+=CaptureTick;}catch(Exception e){Fail(e);}}
 static void CaptureTick(){try{Check();var pos=Eye.transform.position;var rot=Eye.transform.rotation;var aa=Eye.GetComponent<MapCameraFXAA>();
 if(frame<0)Capture("cold-warmup-"+(frame+3),pos,rot,960,540);
 else if(frame==0){aa.enabled=false;Capture("after-eye-no-aa",pos,rot);aa.enabled=true;}
 else if(frame==1)Capture("after-eye-native",pos,rot);
 else if(frame==2)Capture("after-side3m-native",pos+Vector3.right*3,rot);
 else if(frame==3)Capture("after-aerial-native",new Vector3(23,26,-28),Quaternion.LookRotation(new Vector3(-23,-25,30)));
 else if(frame==4)Capture("after-eye-repeat-native",pos,rot);
 else {EditorApplication.update-=CaptureTick;Note("CAPTURE_COMPLETE persisted actual camera/component render; native quality unchanged. managedMemory="+GC.GetTotalMemory(false)+" totalAllocated="+UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong());File.WriteAllText(output+"/final-capture-report.txt",report.ToString());File.WriteAllText(output+"/capture-complete.txt",DateTime.UtcNow.ToString("o"));EditorApplication.Exit(0);}frame++;
 }catch(Exception e){Fail(e);}}
 static string PathOf(Transform t){string s=t.name;while(t.parent!=null){t=t.parent;s=t.name+"/"+s;}return s;}
 static void Capture(string name,Vector3 pos,Quaternion rot,int w=1920,int h=1080){Check();var c=Eye;var oldpos=c.transform.position;var oldrot=c.transform.rotation;var oldfov=c.fieldOfView;var oldrt=c.targetTexture;var prev=RenderTexture.active;var rt=new RenderTexture(w,h,24){antiAliasing=1};var tex=new Texture2D(w,h,TextureFormat.RGB24,false);try{c.transform.SetPositionAndRotation(pos,rot);c.fieldOfView=name.Contains("aerial")?48:44;rt.Create();c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,w,h),0,0);tex.Apply();File.WriteAllBytes(output+"/"+name+".png",tex.EncodeToPNG());}finally{c.targetTexture=oldrt;c.transform.SetPositionAndRotation(oldpos,oldrot);c.fieldOfView=oldfov;RenderTexture.active=prev;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);}Note("Capture "+name+" actualSavedCamera="+c.name+" pos="+pos+" nativeAA0 RT1 noQualityWrite noRenderProbe");}
 static void Fail(Exception e){EditorApplication.update-=FastTick;EditorApplication.update-=MovementTick;EditorApplication.update-=BeforeTick;EditorApplication.update-=BakeTick;EditorApplication.update-=CaptureTick;Debug.LogException(e);if(output!=null)File.WriteAllText(output+"/FAILED.txt",e.ToString());EditorApplication.Exit(1);}
}}
